mapper.select:
SELECT c.id, c.post_id, c.content, c.like_count, c.created_at,
       u.id AS user_id, u.username, u.nickname, u.avatar,
       IF(lk.id IS NOT NULL, TRUE, FALSE) AS is_liked
FROM comment c
JOIN user u ON c.user_id = u.id
LEFT JOIN user_like lk ON lk.target_id = c.id AND lk.target_type = 2 AND lk.user_id = #{userId}
WHERE c.post_id = #{postId}
  AND c.parent_id = 0
  AND c.status = 1

    AND (c.created_at < #{cursorTime}
         OR (c.created_at = #{cursorTime} AND c.id < #{cursorId}))

ORDER BY c.created_at DESC, c.id DESC
LIMIT #{size}
